const SCOUT_P35_ACCOUNT_DISCRIMINATOR: [u8; 8] = [67, 178, 130, 109, 126, 114, 28, 42];
const SCOUT_P35_ACCOUNT_LEN: usize = 8 + 2304;
const SCOUT_P35_BANK_DISCRIMINATOR: [u8; 8] = [142, 49, 166, 242, 50, 66, 97, 188];
const SCOUT_P35_BANK_LEN: usize = 8 + 1856;
const SCOUT_P35_ACCOUNT_FLAGS_OFFSET: usize = 8 + 32 + 32 + 1728;
// user_account.rs:108-113 -- ACCOUNT_IN_FLASHLOAN | ACCOUNT_IN_RECEIVERSHIP | IN_DELEVERAGE.
// Every one of these is a window in which marginfi SUSPENDS the health check by design
// (marginfi_account.rs:548-551 for flashloans, withdraw.rs:195 / kamino/withdraw.rs:200 /
// drift/withdraw.rs:250 / solend/withdraw.rs:207 for receivership), so an account carrying one is
