const SCOUT_GROUP_RATE_LIMITER_LAST_SEQ_OFFSET: usize = 8 + 456;
const SCOUT_GROUP_DELEV_LAST_SLOT_OFFSET: usize = 8 + 464;
const SCOUT_GROUP_DELEV_LAST_SEQ_OFFSET: usize = 8 + 472;
