// 1_500 (update_group_rate_limiter.rs:9, update_deleverage_withdrawals.rs:6).
const SCOUT_FLOW_UPDATE_MAX_LAG_SLOTS: u64 = 1_500;
const SCOUT_P15_GROUP_DAILY_LIMIT_OFFSET: usize = 8 + 272;
const SCOUT_P15_GROUP_WITHDRAWN_TODAY_OFFSET: usize = 8 + 276;
