            let program_bytes: [u8; 16] = data[SCOUT_COLLECT_BANK_FEES_PROGRAM_OFFSET
                ..SCOUT_COLLECT_BANK_FEES_PROGRAM_OFFSET + 16]
                .try_into()
                .unwrap_or_default();
